export function reducer(state:State,action:Action):State{switch(action.type){case "created":{if(state.tickets.some(ticket=>ticket.id===action.ticket.id))throw Error("Powtórzone ID");const ticket={...action.ticket,tags:[...action.ticket.tags]};return {...state,tickets:[ticket,...state.tickets],selectedId:ticket.id};}case "closed":case "reopened":return {...state,tickets:state.tickets.map(ticket=>ticket.id===action.id?{...ticket,status:action.type==="closed"?"CLOSED":"OPEN"}:ticket)};case "assigned":return {...state,tickets:state.tickets.map(ticket=>ticket.id===action.id?{...ticket,assignee:action.assignee}:ticket)};case "updated":return {...state,tickets:state.tickets.map(ticket=>ticket.id===action.id?{...ticket,title:action.changes.title}:ticket)};case "deleted":return {...state,tickets:state.tickets.filter(ticket=>ticket.id!==action.id),selectedId:state.selectedId===action.id?null:state.selectedId};case "selected":return {...state,selectedId:action.id!==null&&state.tickets.some(ticket=>ticket.id===action.id)?action.id:null};case "bulkClosed":{const ids=new Set(action.ids);return {...state,tickets:state.tickets.map(ticket=>ids.has(ticket.id)?{...ticket,status:"CLOSED"}:ticket)};}default:{const exhaustive:never=action;throw Error("Nieznana akcja: "+JSON.stringify(exhaustive));}}}

