const start:State={tickets:[{id:0,title:"API",status:"OPEN",assignee:null,createdAt:"2026-10-29T10:00:00Z",tags:["api"]},{id:1,title:"Drugi",status:"CLOSED",assignee:"piotr",createdAt:"2026-10-29T10:00:00Z",tags:[]}],selectedId:null};const fresh:Ticket={...start.tickets[0],id:2,tags:["ui"]};console.log(init(start.tickets).tickets[0].tags===start.tickets[0].tags);

